def generate_signals(df: pd.DataFrame) -> pd.Series:
    ma60 = df['close'].rolling(window=60).mean()
    ma120 = df['close'].rolling(window=120).mean()

    signals = np.zeros(len(df), dtype=int)
    position = 0
    peak = df['close'].cummax().values
    ma60_vals = ma60.values
    ma120_vals = ma120.values
    close_vals = df['close'].values

    start_idx = 119
    for i in range(start_idx, len(df)):
        if position == 0:
            if ma60_vals[i] > ma120_vals[i] and ma60_vals[i-1] <= ma120_vals[i-1]:
                position = 1
                signals[i] = 1
        else:
            if peak[i] > 0:
                dd = (peak[i] - close_vals[i]) / peak[i]
                if dd >= 0.25:
                    position = 0
                    signals[i] = 0

    return pd.Series(signals, index=df.index)

